  3721→function sanitizePaginationArea(selector) {
  3722→    document.querySelectorAll(selector).forEach(root => {
  3723→        function clean() {
  3724→            // Remove icons (svg, i, img) and large injected nodes
  3725→            root.querySelectorAll('svg,i,img').forEach(e => e.remove());
  3726→            root.querySelectorAll('*').forEach(el => {
  3727→                try {
  3728→                    const rect = el.getBoundingClientRect();
  3729→                    const tag = el.tagName || '';
  3730→                    // Hide any element that's clearly oversized inside pagination
  3731→                    if ((rect.width > 48 || rect.height > 48) && !['BUTTON','A','UL','LI','NAV','SPAN'].includes(tag)) {
  3732→                        el.style.display = 'none';
  3733→                    }
  3734→                    // Ensure buttons/links show text, not icons
  3735→                    if ((tag === 'A' || tag === 'BUTTON' || tag === 'SPAN') && el.querySelectorAll && el.querySelectorAll('svg,i,img').length) {
  3736→                        el.querySelectorAll('svg,i,img').forEach(x=>x.remove());
  3737→                        if (!el.textContent.trim()) {
  3738→                            // set sensible fallback
  3739→                            if (el.getAttribute('aria-label') && /previous/i.test(el.getAttribute('aria-label'))) el.textContent = '‹';
  3740→                            else if (el.getAttribute('aria-label') && /next/i.test(el.getAttribute('aria-label'))) el.textContent = '›';
  3741→                        }
  3742→                    }
  3743→                } catch (e) {
  3744→                    // ignore
  3745→                }
  3746→            });
  3747→        }
  3748→        clean();
  3749→        const mo = new MutationObserver(clean);
  3750→        mo.observe(root, { childList: true, subtree: true, attributes: true });
  3751→    });
  3752→}
