   114→<script>
   115→let currentPage = 1;
   116→
   117→function loadData(page=1) {
   118→    currentPage = page;
   119→    const params = new URLSearchParams({ page, search: document.getElementById('searchInput').value, status: document.getElementById('filterStatus').value, periode: document.getElementById('filterPeriode').value, cabang_id: document.getElementById('filterCabang').value });
   120→    fetch(`{{ route('admin.salaries.index') }}?${params}`, { headers:{'X-Requested-With':'XMLHttpRequest'} })
   121→        .then(r=>r.json()).then(data => {
   122→            document.getElementById('statTotal').textContent   = data.stats.total;
   123→            document.getElementById('statDibayar').textContent = data.stats.dibayar;
   124→            document.getElementById('statPending').textContent = data.stats.pending;
   125→            document.getElementById('statNominal').textContent = 'Rp ' + parseInt(data.stats.total_nominal||0).toLocaleString('id-ID');
   126→            renderTable(data.data);
   127→            renderPagination(data);
   128→        });
   129→}
   130→
   131→function renderTable(rows) {
   132→    const statusMap = { dibayar:'<span class="badge bg-success">Dibayar</span>', pending:'<span class="badge bg-warning text-dark">Pending</span>', batal:'<span class="badge bg-danger">Batal</span>' };
   133→    if (!rows.length) { document.getElementById('tableBody').innerHTML = '<tr><td colspan="8" class="text-center py-5 text-muted">Belum ada data gaji</td></tr>'; return; }
   134→    document.getElementById('tableBody').innerHTML = rows.map(s => `
   135→        <tr>
   136→            <td><div class="fw-semibold">${s.guru?.name||'-'}</div></td>
   137→            <td>${s.periode}</td>
   138→            <td>Rp ${parseInt(s.gaji_pokok||0).toLocaleString('id-ID')}</td>
   139→            <td>${s.jam_mengajar||0} jam</td>
   140→            <td>${s.bonus ? 'Rp '+parseInt(s.bonus).toLocaleString('id-ID') : '-'}</td>
   141→            <td class="fw-bold text-success">Rp ${parseInt(s.total_gaji||0).toLocaleString('id-ID')}</td>
   142→            <td>${statusMap[s.status]||s.status}</td>
   143→            <td><div class="d-flex gap-1">
   144→                <a href="{{ url('admin/salaries') }}/${s.id}/slip" target="_blank" class="btn btn-sm btn-outline-primary" title="Cetak Slip"><i class="bi bi-printer"></i></a>
   145→                <button onclick="editSalary(${s.id})" class="btn btn-sm btn-outline-secondary"><i class="bi bi-pencil"></i></button>
   146→                <button onclick="deleteSalary(${s.id})" class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button>
   147→            </div></td>
   148→        </tr>`).join('');
   149→}
   150→
   151→function renderPagination(data) {
   152→    const el = document.getElementById('paginationLinks');
   153→    if (data.last_page <= 1) { el.innerHTML=''; return; }
   154→    let h = '<nav><ul class="pagination pagination-sm mb-0">';
   155→    h += `<li class="page-item ${data.current_page==1?'disabled':''}"><a class="page-link" href="#" onclick="loadData(${data.current_page-1});return false">‹</a></li>`;
   156→    for(let i=1;i<=data.last_page;i++) h += `<li class="page-item ${i==data.current_page?'active':''}"><a class="page-link" href="#" onclick="loadData(${i});return false">${i}</a></li>`;
   157→    h += `<li class="page-item ${data.current_page==data.last_page?'disabled':''}"><a class="page-link" href="#" onclick="loadData(${data.current_page+1});return false">›</a></li></ul></nav>`;
   158→    el.innerHTML = h;
   159→}
   160→
   161→function openModal(reset=true) {
   162→    if(reset){ document.getElementById('salaryForm').reset(); document.getElementById('salId').value=''; document.getElementById('modalTitle').textContent='Input Gaji Guru'; }
   163→    new bootstrap.Modal(document.getElementById('salaryModal')).show();
   164→}
   165→
   166→function editSalary(id) {
   167→    fetch(`{{ url('admin/salaries') }}/${id}`, { headers:{'X-Requested-With':'XMLHttpRequest'} })
   168→        .then(r=>r.json()).then(res => {
   169→            const s=res.data, f=document.getElementById('salaryForm');
   170→            ['guru_id','periode','gaji_pokok','jam_mengajar','tarif_per_jam','bonus','potongan','status','metode_pembayaran','tanggal_pembayaran','nama_bank','nomor_rekening','catatan'].forEach(k => { if(f.querySelector(`[name=${k}]`)) f.querySelector(`[name=${k}]`).value=s[k]||''; });
   171→            document.getElementById('salId').value = id;
   172→            document.getElementById('modalTitle').textContent = 'Edit Data Gaji';
   173→            openModal(false);
   174→        });
   175→}
   176→
   177→function deleteSalary(id) {
   178→    confirmAction('Hapus data gaji ini? Data tidak dapat dikembalikan.', function() {
   179→        fetch(`{{ url('admin/salaries') }}/${id}`, {method:'DELETE',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','X-Requested-With':'XMLHttpRequest'}})
   180→            .then(r=>r.json()).then(d => { showToast(d.message, d.success?'success':'error'); if(d.success) loadData(currentPage); });
   181→    }, null, {title:'Hapus Data Gaji', okText:'Ya, Hapus'});
   182→}
   183→
   184→document.getElementById('salaryForm').addEventListener('submit', function(e) {
   185→    e.preventDefault();
   186→    const id = document.getElementById('salId').value;
   187→    const url = id ? `{{ url('admin/salaries') }}/${id}` : `{{ route('admin.salaries.store') }}`;
   188→    const fd = new FormData(this);
   189→    if(id) fd.append('_method','PUT');
   190→    document.getElementById('submitBtn').disabled = true;
   191→    fetch(url, {method:'POST',body:fd,headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','X-Requested-With':'XMLHttpRequest'}})
   192→        .then(r=>r.json()).then(d => {
   193→            document.getElementById('submitBtn').disabled = false;
   194→            showToast(d.message, d.success?'success':'error');
   195→            if(d.success){ bootstrap.Modal.getInstance(document.getElementById('salaryModal')).hide(); loadData(currentPage); }
   196→        }).catch(()=>{ document.getElementById('submitBtn').disabled = false; });
   197→});
   198→
   199→function resetFilter() {
   200→    document.getElementById('searchInput').value = '';
   201→    document.getElementById('filterStatus').value = '';
   202→    document.getElementById('filterPeriode').value = '';
   203→    document.getElementById('filterCabang').value = '';
   204→    loadData(1);
   205→}
   206→
   207→let st; document.getElementById('searchInput').addEventListener('input', ()=>{ clearTimeout(st); st=setTimeout(()=>loadData(1),400); });
